pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, uint256 k2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        t1 = bound(t1, 2, type(uint256).max / 2);
        vm.assume(t2 >= 1 && t2 < t1);
        k2 = bound(k2, 1, type(uint256).max / 15);

        // First call at t1 in a non-payout block: succeeds in both P and M,
        // records pastBlockTime = t1 in P, leaves c with 20 ether (no payout).
        vm.warp(t1);
        vm.roll(1); // 1 % 15 != 0
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // Second call at t2 < t1 in a payout block: must revert in P because
        // block.timestamp (t2) is not > pastBlockTime (t1); the mutant never
        // updated pastBlockTime, so it succeeds and transfers away c's balance.
        vm.warp(t2);
        vm.roll(k2 * 15);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(
            ok1 && !ok2 && address(c).balance == 20 ether,
            "second call at t2 <= t1 must revert and c's balance must stay 20 ether"
        );
    }
}

