pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        // keep the block number in the admissible (wide) domain
        blockNum = bound(blockNum, 1, type(uint64).max / 2);
        vm.assume(actor != address(0) && actor != address(c));

        // warp to a fresh timestamp and roll to the fuzzed block
        vm.warp(1000);
        vm.roll(blockNum);

        uint256 preBalance = address(c).balance;

        // drive c through its payable fallback with exactly 10 ether
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        uint256 postBalance = address(c).balance;
        bool paidOut = (postBalance < preBalance);

        // GENERAL RULE: funds are transferred out exactly when block.number % 15 == 0
        assertTrue(paidOut == (block.number % 15 == 0), "payout iff block.number % 15 == 0");
    }
}

