pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 amount, uint256 ts) public {
        amount = bound(amount, 0, 100 ether);
        // ensure admissibility: timestamp strictly advances past stored one
        vm.warp(c.pastBlockTime() + bound(ts, 1, 1e9));
        vm.deal(address(this), amount);
        // drive c through its payable entry via a low-level call (fallback is not directly nameable)
        (bool ok, ) = address(c).call{value: amount}("");
        // General rule: a successful call implies exactly 10 ether was sent.
        // Reference: reverts for any amount != 10 ether (ok == false there).
        // Mutant: accepts any amount, so for amount != 10 ether ok == true, breaking the rule.
        assertTrue(!ok || amount == 10 ether);
    }
}

