pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, address actor) public {
        // pick any block number that is a multiple of 15 (the payout branch)
        blockNumber = bound(blockNumber, 15, type(uint256).max / 2);
        blockNumber = blockNumber - (blockNumber % 15);
        timestamp = bound(timestamp, 1, type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.balance == 0 || actor.balance >= 10 ether);

        vm.roll(blockNumber);
        vm.warp(timestamp);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after a successful call on a block-number divisible by 15,
        // the contract must have paid out its entire balance.
        assertTrue(ok && address(c).balance == 0);
    }
}

