pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Rejecter r;

    function setUp() public {
        c = new C{value: 10 ether}();
        r = new Rejecter(address(c));
    }

    function testFuzz_property(uint256 bn, uint256 ts) public {
        // keep bn in a wide range, then snap to a block divisible by 15 (payout condition)
        bn = bound(bn, 15, 1 << 40);
        bn = bn - (bn % 15);
        vm.assume(ts > 0); // any timestamp past initial pastBlockTime = 0

        vm.roll(bn);
        vm.warp(ts);

        vm.deal(address(r), 10 ether);

        bool ok;
        try r.hit() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on a divisible-by-15 block, C attempts to transfer its
        // balance to msg.sender; if msg.sender rejects ETH the transfer fails
        // and the whole call reverts. The mutant never transfers, so it succeeds.
        assertTrue(!ok);
    }
}

contract Rejecter {
    C immutable c;

    constructor(address target) {
        c = C(target);
    }

    function hit() external payable {
        c.fallback{value: 10 ether}();
    }
    // deliberately no receive/fallback: rejects ETH sent via transfer
}

